 41	function smallestSourceChange(previous: string, next: string): { from: number; to: number; insert: string } | undefined {
 42	  if (previous === next) return undefined;
 43	  let from = 0;
 44	  const shared = Math.min(previous.length, next.length);
 45	  while (from < shared && previous.charCodeAt(from) === next.charCodeAt(from)) from += 1;
 46	  let previousTo = previous.length;
 47	  let nextTo = next.length;
 48	  while (previousTo > from && nextTo > from && previous.charCodeAt(previousTo - 1) === next.charCodeAt(nextTo - 1)) {
 49	    previousTo -= 1;
 50	    nextTo -= 1;
 51	  }
 52	  return { from, to: previousTo, insert: next.slice(from, nextTo) };
 53	}
