    18	}
    19	
    20	export interface ToolbarModel {
    21	  readonly ariaLabel: string;
    22	  readonly groups: readonly ToolbarGroup[];
    23	}
    24	
    25	export interface ToolbarCommandTarget {
    26	  can?(command: string): boolean;
    27	  run(command: string): boolean;
    28	}
    29	
    30	export const defaultToolbarGroups: readonly ToolbarGroup[] = Object.freeze([
    31	  { id: "history", label: "History", actions: [{ id: "undo", label: "Undo", shortcut: "Mod-z" }, { id: "redo", label: "Redo", shortcut: "Mod-Shift-z" }] },
    32	  { id: "inline", label: "Inline formatting", actions: [{ id: "bold", label: "Bold", command: "bold", shortcut: "Mod-b" }, { id: "italic", label: "Italic", command: "italic", shortcut: "Mod-i" }, { id: "code", label: "Code", command: "inline-code" }] },
    33	  { id: "blocks", label: "Blocks", actions: [{ id: "heading-2", label: "Heading", command: "heading-2" }, { id: "bullet-list", label: "Bullet list", command: "bullet-list" }, { id: "ordered-list", label: "Numbered list", command: "ordered-list" }, { id: "blockquote", label: "Quote", command: "blockquote" }] },
    34	]);
    35	
    36	export function createToolbarModel(controller: EditorController, groups: readonly ToolbarGroup[] = defaultToolbarGroups, ariaLabel = "Markdown formatting", commandTarget?: ToolbarCommandTarget | null): ToolbarModel {
    37	  const canRun = (command: string): boolean => commandTarget?.can?.(command) ?? controller.can(command);
    38	  return {
    39	    ariaLabel,
    40	    groups: groups.map((group) => ({
    41	      ...group,
    42	      actions: group.actions.map((action) => ({
    43	        ...action,
    44	        disabled: action.id === "undo" ? !(commandTarget?.can?.("undo") ?? controller.canUndo()) : action.id === "redo" ? !(commandTarget?.can?.("redo") ?? controller.canRedo()) : action.command ? !canRun(action.command) : action.disabled,
    45	      })),
    46	    })),
    47	  };
    48	}
    49	
    50	export function runToolbarAction(controller: EditorController, action: ToolbarAction, commandTarget?: ToolbarCommandTarget | null): boolean {
    51	  if (action.disabled) return false;
    52	  if (commandTarget) return commandTarget.run(action.command ?? action.id);
    53	  if (action.id === "undo") return controller.undo();
    54	  if (action.id === "redo") return controller.redo();
    55	  return action.command ? controller.run(action.command) : false;
    56	}
