 41	export function createDirectiveExtension(options: DirectiveExtensionOptions): MdfnExtension {
 42	  const name = directiveName(options.name);
 43	  const nodeType = `directive-${name}`;
 44	  return {
 45	    name: `directive/${name}`,
 46	    version: options.version ?? "1.0.0",
 47	    dependencies: ["commonmark"],
 48	    schema: { nodes: [nodeType] },
 49	    preservation: exactPreservation,
 50	    security: { allowsRawHtml: false },
 51	    parseMarkdown({ source, offset, line }) {
 52	      const opening = new RegExp(`^:::\\s*${name}(?:\\s+([^\\r\\n]*))?\\s*(?:\\r?\\n|$)`).exec(line);
 53	      if (!opening) return null;
 54	      const searchFrom = offset + line.length;
 55	      const closePattern = /^:{3,}\s*$/gm;
 56	      closePattern.lastIndex = searchFrom;
 57	      const close = closePattern.exec(source);
 58	      const closeEnd = close ? close.index + close[0].length + (source[close.index + close[0].length] === "\r" ? 2 : source[close.index + close[0].length] === "\n" ? 1 : 0) : source.length;
 59	      const bodyEnd = close?.index ?? source.length;
 60	      const body = source.slice(searchFrom, bodyEnd).replace(/\r?\n$/, "");
 61	      return {
 62	        consumed: closeEnd - offset,
 63	        node: {
 64	          type: nodeType,
 65	          attrs: { name, label: opening[1]?.trim() || options.label || name },
 66	          text: body,
 67	        },
 68	        diagnostics: close ? [] : [{ code: "MDFN_DIRECTIVE_UNCLOSED", message: `Directive ${name} has no closing fence`, severity: "warning", source: { from: offset, to: source.length }, extension: `directive/${name}` }],
 69	      };
 70	    },
 71	    serializeMarkdown({ node }) {
 72	      if (node.type !== nodeType) return null;
 73	      const label = typeof node.attrs?.label === "string" && node.attrs.label !== name ? ` ${node.attrs.label}` : "";
 74	      return `:::${name}${label}\n${node.text ?? ""}\n:::`;
 75	    },
 76	    render({ node, escape }) {
 77	      if (node.type !== nodeType) return null;
 78	      const label = typeof node.attrs?.label === "string" ? node.attrs.label : options.label ?? name;
 79	      const className = options.className ? ` ${escape(options.className)}` : "";
 80	      return `<aside class="mdfn-directive mdfn-directive-${escape(name)}${className}" data-md-directive="${escape(name)}"><strong>${escape(label)}</strong><p>${escape(node.text ?? "").replaceAll("\n", "<br>")}</p></aside>`;
 81	    },
