    70	      if (change.documentChanged) {
    71	        const current = source.toString();
    72	        const range = changedRange(current, change.current.markdown);
    73	        if (range.to > range.from) source.delete(range.from, range.to - range.from);
    74	        if (range.inserted) source.insert(range.from, range.inserted);
    75	      }
    76	      if (change.sidecarChanged) {
    77	        if (change.current.sidecar) sidecar.set("value", JSON.stringify(change.current.sidecar));
    78	        else sidecar.delete("value");
    79	      }
    80	    }, localOrigin);
    81	  });
