    25	export function createMemoryAssetProvider(options: { readonly baseUrl?: string; readonly createId?: () => string; readonly maxBytes?: number; readonly allowedMediaTypes?: readonly string[] } = {}): MdfnAssetProvider {
    26	  const assets = new Map<string, { metadata: StoredAsset; bytes: Uint8Array }>();
