     1	import type { ChangedRange, MdfnSidecar, SidecarAnchor } from "./types";
     2	
     3	function mapPosition(position: number, range: ChangedRange, affinity: "before" | "after"): number {
     4	  const removed = range.to - range.from;
     5	  const delta = range.insertedLength - removed;
     6	  if (position < range.from || (position === range.from && affinity === "before")) return position;
     7	  if (position > range.to || (position === range.to && affinity === "after")) return position + delta;
     8	  return affinity === "before" ? range.from : range.from + range.insertedLength;
     9	}
    10	
    11	export function mapAnchor(anchor: SidecarAnchor, ranges: readonly ChangedRange[]): SidecarAnchor {
    12	  return ranges.reduce<SidecarAnchor>((current, range) => {
    13	    const affinity = current.affinity ?? "after";
    14	    const from = mapPosition(current.from, range, affinity === "before" ? "before" : "after");
    15	    const to = mapPosition(current.to, range, affinity === "after" ? "after" : "before");
    16	    return { ...current, from: Math.min(from, to), to: Math.max(from, to) };
    17	  }, anchor);
    18	}
    19	
    20	export function mapSidecar(sidecar: MdfnSidecar | undefined, ranges: readonly ChangedRange[]): MdfnSidecar | undefined {
    21	  if (!sidecar || ranges.length === 0) return sidecar;
    22	  return {
    23	    ...sidecar,
    24	    comments: sidecar.comments?.map((thread) => ({ ...thread, anchor: mapAnchor(thread.anchor, ranges) })),
    25	    suggestions: sidecar.suggestions?.map((suggestion) => ({ ...suggestion, anchor: mapAnchor(suggestion.anchor, ranges) })),
    26	  };
    27	}

