   288	export function extractChunks(document: MdfnDocument, maxCharacters = 2_000): Array<{ text: string; heading?: string }> {
   289	  const chunks: Array<{ text: string; heading?: string }> = [];
   290	  let heading: string | undefined;
   291	  let buffer = "";
   292	  const flush = (): void => {
   293	    const text = buffer.trim();
   294	    if (text) chunks.push({ text, heading });
   295	    buffer = "";
   296	  };
   297	  for (const node of document.content) {
   298	    if (node.type === "heading") {
   299	      flush();
   300	      heading = plainText(node).trim();
   301	      continue;
   302	    }
   303	    const text = plainText(node).trim();
   304	    if (!text) continue;
   305	    if (buffer && buffer.length + text.length + 2 > maxCharacters) flush();
   306	    buffer += `${buffer ? "\n\n" : ""}${text}`;
   307	  }
