    30	function diagnostics(controller: EditorController): CodeMirrorDiagnostic[] {
    31	  const length = controller.getState().markdown.length;
    32	  return controller.getState().diagnostics.map((entry) => ({
    33	    from: Math.max(0, Math.min(length, entry.source?.from ?? 0)),
    34	    to: Math.max(0, Math.min(length, entry.source?.to ?? entry.source?.from ?? 0)),
    35	    severity: entry.severity === "error" ? "error" : entry.severity === "warning" ? "warning" : "info",
    36	    message: entry.message,
