    94	      };
    95	      visit(document);
    96	      return diagnostics;
    97	    },
    98	    migrations: [{
    99	      from: 1,
   100	      to: 2,
   101	      migrate(document: MdfnDocument): MdfnDocument {
   102	        const migrate = (node: MdfnNode): MdfnNode => node.type === `callout-${name}`
   103	          ? { ...node, type: nodeType }
   104	          : { ...node, content: node.content?.map(migrate) };
