     1	import { resolveExtensions, type MdfnExtension, type ResolvedExtensionRegistry } from "@mdfn/core";
     2	
     3	export interface MdfnProfile {
     4	  readonly name: string;
     5	  readonly version: string;
     6	  readonly extensions: readonly string[];
     7	  readonly description?: string;
     8	  readonly rawHtml?: "disabled" | "sanitized";
     9	}
    10	
    11	export interface ResolvedMdfnProfile extends MdfnProfile {
    12	  readonly registry: ResolvedExtensionRegistry;
    13	}
    14	
    15	export interface MdfnRegistry {
    16	  registerExtension(extension: MdfnExtension): void;
    17	  registerProfile(profile: MdfnProfile): void;
    18	  extension(name: string): MdfnExtension | undefined;
    19	  profile(name: string): ResolvedMdfnProfile;
    20	  listExtensions(): readonly MdfnExtension[];
    21	  listProfiles(): readonly MdfnProfile[];
    22	}
    23	
    24	export function createRegistry(input: { readonly extensions?: readonly MdfnExtension[]; readonly profiles?: readonly MdfnProfile[] } = {}): MdfnRegistry {
    25	  const extensions = new Map<string, MdfnExtension>();
    26	  const profiles = new Map<string, MdfnProfile>();
    27	  const registerExtension = (extension: MdfnExtension): void => {
    28	    if (extensions.has(extension.name)) throw new Error(`MDFN_REGISTRY_EXTENSION_EXISTS:${extension.name}`);
    29	    // Resolve a complete temporary set so dependency and security policy errors surface at registration time.
    30	    resolveExtensions([...extensions.values(), extension]);
    31	    extensions.set(extension.name, extension);
    32	  };
    33	  for (const extension of input.extensions ?? []) registerExtension(extension);
    34	  const registerProfile = (profile: MdfnProfile): void => {
    35	    if (!profile.name || !profile.version) throw new Error("MDFN_REGISTRY_PROFILE_INVALID");
    36	    if (profiles.has(profile.name)) throw new Error(`MDFN_REGISTRY_PROFILE_EXISTS:${profile.name}`);
    37	    for (const name of profile.extensions) if (!extensions.has(name)) throw new Error(`MDFN_REGISTRY_PROFILE_EXTENSION_MISSING:${name}`);
    38	    profiles.set(profile.name, Object.freeze({ ...profile, extensions: Object.freeze([...profile.extensions]) }));
    39	  };
    40	  for (const profile of input.profiles ?? []) registerProfile(profile);
    41	  return {
    42	    registerExtension,
    43	    registerProfile,
    44	    extension: (name) => extensions.get(name),
    45	    profile(name) {
    46	      const profile = profiles.get(name);
    47	      if (!profile) throw new Error(`MDFN_REGISTRY_PROFILE_MISSING:${name}`);
    48	      const selected = new Map<string, MdfnExtension>();
    49	      const include = (extensionName: string): void => {
    50	        if (selected.has(extensionName)) return;
    51	        const extension = extensions.get(extensionName);
    52	        if (!extension) throw new Error(`MDFN_REGISTRY_PROFILE_EXTENSION_MISSING:${extensionName}`);
    53	        for (const dependency of extension.dependencies ?? []) include(dependency);
    54	        selected.set(extensionName, extension);
    55	      };
    56	      for (const extension of profile.extensions) include(extension);
    57	      return { ...profile, registry: resolveExtensions([...selected.values()]) };
    58	    },
    59	    listExtensions: () => Object.freeze([...extensions.values()]),
    60	    listProfiles: () => Object.freeze([...profiles.values()]),
    61	  };
    62	}
    63	
    64	export const MDFN_REGISTRY_VERSION = "0.1.0" as const;

