     1	import { describe, expect, it } from "vitest";
     2	import { deterministicFuzzCorpus, compareSemanticTraces, representativeCorpus, runPreservationCorpus, runSecurityCorpus } from "./index";
     3	import { parseMarkdown, serializeMarkdown } from "@mdfn/markdown";
     4	import { renderHtml } from "@mdfn/render";
     5	import { tests as commonmarkSpecTests } from "commonmark-spec";
     6	
     7	describe("@mdfn/testing", () => {
     8	  it("passes the representative no-edit corpus", () => {
     9	    const result = runPreservationCorpus(representativeCorpus);
    10	    expect(result).toMatchObject({ ok: true, failed: 0, passed: representativeCorpus.length });
    11	  });
    12	
    13	  it("detects executable render output and adapter divergence", () => {
    14	    const safe = runSecurityCorpus({ type: "doc", schemaVersion: 1, content: [{ type: "opaque", attrs: { syntax: "html" }, text: "<script>bad()</script>" }] });
    15	    expect(safe.ok).toBe(true);
    16	    const reference = { schemaVersion: 1 as const, framework: "vanilla" as const, fixture: "basic", steps: [], finalMarkdown: "a", finalSelection: null, diagnostics: [], cleanup: { subscriptions: 0, mounted: false } };
    17	    const result = compareSemanticTraces(reference, [{ ...reference, framework: "react", finalMarkdown: "b" }]);
    18	    expect(result.ok).toBe(false);
    19	  });
    20	
    21	  it("passes a reproducible malformed and Unicode fuzz corpus", () => {
    22	    const corpus = deterministicFuzzCorpus(0x53464e20, 128);
    23	    expect(runPreservationCorpus(corpus)).toMatchObject({ ok: true, passed: 128, failed: 0 });
    24	  });
    25	
    26	  it("parses and byte-preserves every official CommonMark 0.31.2 example", () => {
    27	    const corpus = commonmarkSpecTests.map((example) => ({ id: `commonmark-${example.number}-${example.section}`, source: example.markdown, options: { dialect: "commonmark" as const } }));
    28	    expect(corpus.length).toBeGreaterThan(600);
    29	    expect(runPreservationCorpus(corpus)).toMatchObject({ ok: true, passed: corpus.length, failed: 0 });
    30	  });
    31	
    32	  it("stays within the documented large-document development budget", () => {
    33	    const source = `${"## Heading\n\nParagraph with **bold**, [link](https://example.com), and 日本語.\n\n".repeat(3_200)}`;
    34	    const started = performance.now();
    35	    const parsed = parseMarkdown(source);
    36	    const serialized = serializeMarkdown({ document: parsed.document, originalSource: source });
    37	    const rendered = renderHtml(parsed.document);
    38	    const elapsed = performance.now() - started;
    39	    expect(source.length).toBeGreaterThan(200_000);
    40	    expect(serialized.markdown).toBe(source);
    41	    expect(rendered.html.length).toBeGreaterThan(100_000);
    42	    expect(elapsed).toBeLessThan(5_000);
    43	  }, 10_000);
    44	});

