     1	import { describe, expect, it } from "vitest";
     2	import { memoryAdapter } from "@superfunctions/db/adapters/memory";
     3	import { createMdfnService } from "./index";
     4	
     5	describe("mdfn server", () => {
     6	  it("wraps the adapter and enforces optimistic versions", async () => {
     7	    const database = memoryAdapter();
     8	    const service = createMdfnService({ database, durability: "ephemeral", authorize: () => true, createId: (() => { let id = 0; return () => `id-${id++}`; })() });
     9	    const principal = { id: "u" };
