    12	    expect(updated.version).toBe(2);
    13	    await expect(service.update(principal, created.id, { expectedVersion: 1, markdown: "# Three" })).rejects.toMatchObject({ code: "MDFN_VERSION_CONFLICT" });
    14	    expect(await service.versions(principal, created.id)).toHaveLength(2);
    15	  });
    16	
    17	  it("enforces tenant scope before host authorization and collaboration limits", async () => {
    18	    const database = memoryAdapter();
    19	    const service = createMdfnService({ database, durability: "ephemeral", authorize: () => true, maxCollaborationUpdateBytes: 4, createId: (() => { let id = 0; return () => `tenant-id-${id++}`; })() });
    20	    const created = await service.create({ id: "a", tenantId: "tenant-a" }, { markdown: "# Scoped" });
    21	    await expect(service.read({ id: "b", tenantId: "tenant-b" }, created.id)).rejects.toMatchObject({ code: "MDFN_DOCUMENT_NOT_FOUND" });
    22	    await expect(service.appendCollaborationUpdate({ id: "a", tenantId: "tenant-a" }, created.id, "12345")).rejects.toMatchObject({ code: "MDFN_COLLAB_UPDATE_TOO_LARGE", status: 413 });
    23	  });
    24	
    25	  it("fails closed when durable storage lacks transaction support", () => {
    26	    expect(() => createMdfnService({ database: memoryAdapter(), authorize: () => true })).toThrowError("MDFN_TRANSACTIONAL_DATABASE_REQUIRED");
    27	  });
    28	
    29	  it("persists editorial workflows, restores revisions, and compacts collaboration state", async () => {
    30	    const service = createMdfnService({ database: memoryAdapter(), durability: "ephemeral", authorize: () => true, createId: (() => { let id = 0; return () => `workflow-${id++}`; })() });
