   937	export function compileMarkdown(input: CompileMarkdownInput): CompiledContentArtifact {
   938	  try {
   939	    const framework = input.framework ?? "core";
   940	    let transformedSource = input.source;
   941	    const componentsUsed = new Set<string>();
   942	    let resolvedComponents: Set<string> | undefined;
   943	
   944	    if (input.compatPreset === "fumadocs-v15") {
   945	      const compat = transformFumadocsV15({
   946	        source: transformedSource,
   947	        sourcePath: input.sourcePath,
   948	      });
   949	      transformedSource = compat.transformed;
   950	      resolvedComponents = compat.importedComponents;
   951	      for (const componentName of compat.componentsUsed) {
   952	        componentsUsed.add(componentName);
   953	      }
   954	    }
   955	
   956	    assertSafeSource({
   957	      source: transformedSource,
   958	      sourcePath: input.sourcePath,
   959	      allowRawHtml: input.allowRawHtml,
   960	    });
   961	
   962	    const canonical = parseMarkdown(transformedSource, {
   963	      dialect: "gfm",
   964	      allowRawHtml: input.allowRawHtml ?? false,
   965	      extensions: defaultExtensions,
   966	    });
   967	
   968	    const blocks = projectCanonicalBlocks({
   969	      document: canonical.document,
   970	      source: transformedSource,
   971	      sourcePath: input.sourcePath,
   972	      resolvedComponents,
   973	      idPrefix: normalizeRouteLikeId(input.sourcePath, "inline"),
   974	    });
   975	    const headings = blocks
   976	      .filter((block): block is Extract<CompiledContentBlock, { type: "heading" }> => block.type === "heading")
   977	      .map((block) => ({
   978	        level: block.level,
   979	        text: block.text,
   980	        slug: block.slug,
   981	      }));
   982	
   983	    if (blocks.some((block) => block.type === "tabs")) {
   984	      componentsUsed.add("DocsTabs");
   985	      componentsUsed.add("DocsTab");
   986	    }
   987	    if (blocks.some((block) => block.type === "mermaid")) {
   988	      componentsUsed.add("MermaidBlock");
   989	    }
   990	    if (blocks.some((block) => block.type === "callout")) {
   991	      componentsUsed.add("Callout");
   992	    }
   993	
   994	    return {
   995	      framework,
   996	      renderModelVersion: 2,
   997	      source: input.source,
   998	      transformedSource,
   999	      blocks,
  1000	      headings,
  1001	      toc: headings,
  1002	      componentsUsed: [...componentsUsed].sort((left, right) => left.localeCompare(right)),
  1003	      diagnostics: projectMarkdownDiagnostics(canonical.diagnostics, input.sourcePath),
  1004	    };
  1005	  } catch (error) {
  1006	    if (isDocsError(error)) {
  1007	      throw error;
  1008	    }
