  1010	      message: "failed to compile markdown content",
  1011	      sourcePath: input.sourcePath,
  1012	      details: {
  1013	        error: error instanceof Error ? error.message : String(error),
  1014	      },
  1015	    });
  1016	  }
  1017	}
