 75	    if (visited.has(name)) return;
 76	    if (visiting.has(name)) {
 77	      throw new ExtensionGraphError(
 78	        "MDFN_EXTENSION_CYCLE",
 79	        `Extension dependency cycle: ${[...path, name].join(" -> ")}`,
 80	        name,
